def port_display_setting(apps, schema_editor):
    """Turn the old single DisplaySetting row into the default station."""
    DisplaySetting = apps.get_model("products", "DisplaySetting")
    DisplayProfile = apps.get_model("products", "DisplayProfile")

    old = DisplaySetting.objects.first()
    values = {field: getattr(old, field) for field in _CARRIED_OVER} if old else {}

    DisplayProfile.objects.update_or_create(
        slug="default",
        defaults={"name": "Default", "is_default": True, "is_active": True, **values},
    )


def unport_display_setting(apps, schema_editor):
    """Reverse: recreate the singleton from the default station."""
    DisplaySetting = apps.get_model("products", "DisplaySetting")
    DisplayProfile = apps.get_model("products", "DisplayProfile")

    profile = DisplayProfile.objects.filter(is_default=True).first()
    if profile is None:
        return
    values = {field: getattr(profile, field) for field in _CARRIED_OVER}
    DisplaySetting.objects.update_or_create(pk=1, defaults=values)


